function contentLang(lang: string): ContentLang {
  if (lang === "hn" || lang === "hi") return lang;
  return "en";
}

function pick(lang: string, key: string): string {
  const l = contentLang(lang);
  const v = DICTS[l][key];
  return typeof v === "string" && v.length ? v : (DICTS.en[key] ?? key);
}

function pickRange(lang: string, prefix: string, n: number): string[] {
  const out: string[] = [];
  for (let i = 0; i < n; i++) out.push(pick(lang, prefix + "_" + i));
  return out;
}

export function getMonthsFull(lang: string): string[] {
  return [pick(lang, "month_full_jan"), pick(lang, "month_full_feb"), pick(lang, "month_full_mar"), pick(lang, "month_full_apr"), pick(lang, "month_full_may"), pick(lang, "month_full_jun"), pick(lang, "month_full_jul"), pick(lang, "month_full_aug"), pick(lang, "month_full_sep"), pick(lang, "month_full_oct"), pick(lang, "month_full_nov"), pick(lang, "month_full_dec")];
}

export function getMonthsShort(lang: string): string[] {
  return [pick(lang, "month_short_jan"), pick(lang, "month_short_feb"), pick(lang, "month_short_mar"), pick(lang, "month_short_apr"), pick(lang, "month_short_may"), pick(lang, "month_short_jun"), pick(lang, "month_short_jul"), pick(lang, "month_short_aug"), pick(lang, "month_short_sep"), pick(lang, "month_short_oct"), pick(lang, "month_short_nov"), pick(lang, "month_short_dec")];
}

export function getDemoLabels(lang: string): string[] {
  const lbl = {
    p10: pick(lang, "demo_lbl_10pm"),
    p1:  pick(lang, "demo_lbl_1am"),
    p4:  pick(lang, "demo_lbl_4am"),
    p7:  pick(lang, "demo_lbl_7am"),
    now: pick(lang, "demo_lbl_now"),
  };
  return [lbl.p10, "", "", lbl.p1, "", "", lbl.p4, "", "", lbl.p7, "", lbl.now];
}

export function getPYTheme(lang: string, n: number): string {
  return pick(lang, "py_theme_" + n);
}

